import { createItem, addVersion } from '@projexlight/sdk-content';
const { item_id } = await createItem({
  tenant_id, slug: 'eu-q3-data-residency', kind: 'article', owner_persona_id,
});
const { version_id } = await addVersion({
  item_id, body_html: '<p>...</p>', locale: 'en-US',
});

subscribeEvents('approval.request.approved.v1', async (e) => {
  if (e.payload.subject_kind !== 'content.version') return;
  await publishVersion({ version_id: e.payload.subject_id });
});

import { applyTags } from '@projexlight/sdk-content';
await applyTags({
  item_id, taxonomy_id: 'industry-tags',
  add: ['data-residency','eu','enterprise'], remove: [],
});

import { retireVersion } from '@projexlight/sdk-content';
await retireVersion({
  version_id, reason: 'compliance-out-of-date',
  retired_by_persona_id,
});

